Add-Type -TypeDefinition @'
using System;
using System.Threading;
public sealed class CurrentLease : IDisposable {
 private Semaphore sem;public bool Acquired{get;private set;}public string Name{get;private set;}public string Status{get;private set;}
 public CurrentLease(string name,int maximum,int count,int timeout,string cancel){
  if(String.IsNullOrWhiteSpace(name)||name.Length>240||maximum<1||maximum>32||count<1||count>maximum||timeout<0||timeout>60000)throw new ArgumentException("Invalid lease request");
  Name=name;sem=new Semaphore(maximum,maximum,name);Acquired=sem.WaitOne(timeout);Status=Acquired?"Acquired":"TimedOut";
 }
 public void Dispose(){if(sem!=null){sem.Release();sem.Dispose();}}
}
'@
function Open-WindowsSemaphoreLease {
 [CmdletBinding()]
 param([Parameter(Mandatory=$true)][string]$Name,[int]$MaximumCount=1,[int]$PermitCount=1,[int]$TimeoutMilliseconds=0,[string]$CancellationEventName)
 [CurrentLease]::new($Name,$MaximumCount,$PermitCount,$TimeoutMilliseconds,$CancellationEventName)
}
Export-ModuleMember -Function Open-WindowsSemaphoreLease

