Add-Type -TypeDefinition @'
using System;using System.IO;
// Legacy window implementation. It buffers a snapshot instead of a shared view.
public sealed class BufferedFileWindow : IDisposable {
 readonly object gate=new object();FileStream file;byte[] data;bool disposed;
 public long Offset{get;private set;}public int Length{get;private set;}public bool Writable{get;private set;}public bool IsDisposed{get{lock(gate){return disposed;}}}
 public static BufferedFileWindow Open(string path,long offset,int length,bool writable){
  if(offset<0||length<1||length>16777216||offset>long.MaxValue-length)throw new ArgumentOutOfRangeException("range");
  if(String.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path)||path.Length<3||path[1]!=':'||path.StartsWith(@"\\")||path.IndexOf(':',2)>=0)throw new ArgumentException("path");
  if((File.GetAttributes(path)&(FileAttributes.Directory|FileAttributes.ReparsePoint))!=0)throw new ArgumentException("ordinary file required");
  var w=new BufferedFileWindow();w.Offset=offset;w.Length=length;w.Writable=writable;
  try{w.file=new FileStream(path,FileMode.Open,writable?FileAccess.ReadWrite:FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);if(offset+length>w.file.Length)throw new ArgumentOutOfRangeException("range");w.data=new byte[length];w.file.Position=offset;int n=0;while(n<length){int k=w.file.Read(w.data,n,length-n);if(k==0)throw new EndOfStreamException();n+=k;}return w;}catch{w.Dispose();throw;}
 }
 void Alive(){if(disposed)throw new ObjectDisposedException("window");}
 void Bounds(int offset,int count){if(offset<0||count<0||offset>Length||count>Length-offset)throw new ArgumentOutOfRangeException("range");}
 public byte[] Read(int offset,int count){lock(gate){Alive();Bounds(offset,count);var b=new byte[count];Array.Copy(data,offset,b,0,count);return b;}}
 public void Write(int offset,byte[] bytes){lock(gate){Alive();if(bytes==null)throw new ArgumentNullException("bytes");Bounds(offset,bytes.Length);if(!Writable)throw new InvalidOperationException("read only");Array.Copy(bytes,0,data,offset,bytes.Length);}}
 public void Flush(){lock(gate){Alive();if(Writable){file.Position=Offset;file.Write(data,0,data.Length);file.Flush(true);}}}
 public void Dispose(){lock(gate){if(disposed)return;disposed=true;if(file!=null){file.Dispose();file=null;}data=null;}}
}
'@
function Open-WindowsMappedWindow {
 [CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][long]$Offset,[Parameter(Mandatory=$true)][int]$Length,[switch]$Writable)
 [BufferedFileWindow]::Open($Path,$Offset,$Length,[bool]$Writable)
}
