$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @'
using System;using System.Threading;using Microsoft.Win32;
// The old waiter retains a key but has no working change-notification channel.
public sealed class IncompleteRegistryWatch : IDisposable {
 readonly object gate=new object();RegistryKey key;ManualResetEvent stop=new ManualResetEvent(false);bool disposed;int waiting;
 public bool IsDisposed{get{lock(gate){return disposed;}}}
 public static IncompleteRegistryWatch Open(string root,string sub,string view,bool subtree,string filter){
  if(String.IsNullOrWhiteSpace(sub)||sub.StartsWith("\\")||sub.EndsWith("\\")||sub.Contains("\\\\")||sub.IndexOf('\0')>=0)throw new ArgumentException("subkey");
  RegistryHive hive;if(root=="CurrentUser")hive=RegistryHive.CurrentUser;else if(root=="LocalMachine")hive=RegistryHive.LocalMachine;else throw new ArgumentException("root");
  RegistryView v;if(view=="Registry64")v=RegistryView.Registry64;else if(view=="Registry32")v=RegistryView.Registry32;else throw new ArgumentException("view");
  if(filter!="Name"&&filter!="Value"&&filter!="NameAndValue")throw new ArgumentException("filter");
  var w=new IncompleteRegistryWatch();try{using(var b=RegistryKey.OpenBaseKey(hive,v)){w.key=b.OpenSubKey(sub,false);if(w.key==null)throw new ArgumentException("missing key");}return w;}catch{w.Dispose();throw;}
 }
 public string Wait(int timeoutMilliseconds,string cancellationEventName){
  if(timeoutMilliseconds<0||timeoutMilliseconds>60000)throw new ArgumentOutOfRangeException("timeoutMilliseconds");
  EventWaitHandle cancel=null;try{if(!String.IsNullOrEmpty(cancellationEventName))cancel=EventWaitHandle.OpenExisting(cancellationEventName);
   if(Interlocked.CompareExchange(ref waiting,1,0)!=0)throw new InvalidOperationException("one waiter only");
   try{lock(gate){if(disposed)return "Disposed";}int i=cancel==null?(stop.WaitOne(timeoutMilliseconds)?0:WaitHandle.WaitTimeout):WaitHandle.WaitAny(new WaitHandle[]{stop,cancel},timeoutMilliseconds);lock(gate){if(disposed)return "Disposed";return i==1?"Cancelled":"TimedOut";}}
   finally{Interlocked.Exchange(ref waiting,0);lock(gate){if(disposed)Close();}}
  }finally{if(cancel!=null)cancel.Dispose();}
 }
 void Close(){if(key!=null){key.Dispose();key=null;}if(stop!=null){stop.Dispose();stop=null;}}
 public void Dispose(){lock(gate){if(disposed)return;disposed=true;stop.Set();if(Interlocked.CompareExchange(ref waiting,0,0)==0)Close();}}
}
'@
function Open-WindowsRegistryWatch {
 [CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$SubKey,[string]$View='Registry64',[switch]$WatchSubtree,[string]$Filter='NameAndValue')
 [IncompleteRegistryWatch]::Open($Root,$SubKey,$View,[bool]$WatchSubtree,$Filter)
}
Export-ModuleMember -Function Open-WindowsRegistryWatch

