function Read-WindowsEventBatch {
 [CmdletBinding()]
 param([Parameter(Mandatory=$true)][string]$LogName,[string]$Cursor='', [int]$MaxEvents=100,[int[]]$EventIds=@())
 $ErrorActionPreference='Stop'
 if($MaxEvents-lt1-or$MaxEvents-gt512){throw 'MaxEvents must be 1..512'}
 foreach($id in $EventIds){if($id-lt0-or$id-gt65535){throw 'Invalid EventId'}}
 if([string]::IsNullOrWhiteSpace($LogName)-or-not[Diagnostics.EventLog]::Exists($LogName)){throw 'Existing local log required'}
 $filter=@($EventIds|Sort-Object -Unique);$signature=$filter-join',';$bound=$LogName.ToUpperInvariant();$last=0L;$lastXml=''
 if($Cursor){
  try{$c=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Cursor))|ConvertFrom-Json;if($c.v-ne2-or$c.last-isnot[valuetype]-or$c.last-lt0-or$c.xml-isnot[string]){throw 'Invalid cursor'};$last=[long]$c.last;$lastXml=[string]$c.xml}catch{throw 'Cursor malformed or input mismatch'}
 }
 $q=[Diagnostics.Eventing.Reader.EventLogQuery]::new($LogName,[Diagnostics.Eventing.Reader.PathType]::LogName);$q.ReverseDirection=$true;$r=$null;$high=0L
 try{$r=[Diagnostics.Eventing.Reader.EventLogReader]::new($q);$ev=$r.ReadEvent();if($ev){try{$high=[long]$ev.RecordId}finally{$ev.Dispose()}}}finally{if($r){$r.Dispose()}}
 if($last-gt$high){$last=0L}
 $out=[Collections.Generic.List[object]]::new();$end=$true;$r=$null
 try{
  $query='*[System[(EventRecordID >= '+$last+') and (EventRecordID <= '+$high+')]]'
  $q=[Diagnostics.Eventing.Reader.EventLogQuery]::new($LogName,[Diagnostics.Eventing.Reader.PathType]::LogName,$query);$q.ReverseDirection=$false;$r=[Diagnostics.Eventing.Reader.EventLogReader]::new($q)
  while($null-ne($ev=$r.ReadEvent())){
   try{
    $matches=($filter.Count-eq0-or$filter-contains[int]$ev.Id)
    if($matches-and$out.Count-eq$MaxEvents){$end=$false;break}
    $last=[long]$ev.RecordId;$lastXml=$ev.ToXml()
    if($matches){$out.Add([pscustomobject]@{RecordId=[long]$ev.RecordId;Provider=[string]$ev.ProviderName;EventId=[int]$ev.Id;Level=[int]$ev.Level;TimeCreatedUtc=$ev.TimeCreated.ToUniversalTime().ToString('o');Xml=$lastXml})}
   }finally{$ev.Dispose()}
  }
 }finally{if($r){$r.Dispose()}}
 $next=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes((@{v=2;log=$bound;filter=$signature;last=$last;xml=$lastXml}|ConvertTo-Json -Compress)))
 [pscustomobject]@{Events=[object[]]$out.ToArray();Cursor=$next;EndOfFile=[bool]($end-and$out.Count-lt$MaxEvents);HighWaterRecordId=[long]$high}
}
