public static class CompoundPatch {
 [DllImport("ole32.dll",CharSet=CharSet.Unicode,PreserveSig=false)]
 static extern void StgOpenStorage(string path,IPatchStorage priority,uint mode,IntPtr exclude,uint reserved,out IPatchStorage storage);
 static void Release(object x){if(x!=null&&Marshal.IsComObject(x))Marshal.FinalReleaseComObject(x);}
 static string Segment(object x){
  string s=x as string;if(String.IsNullOrEmpty(s)||s.Length>31)throw new ArgumentException("Invalid storage name");
  foreach(char c in s)if(c<' '||c=='\\'||c=='/'||c==':'||c=='!')throw new ArgumentException("Invalid storage name");return s;
 }
 public static int Apply(string path,string patchJson){
  if(String.IsNullOrEmpty(path)||!Path.IsPathRooted(path)||!File.Exists(path))throw new ArgumentException("Existing absolute compound file required");
  var serializer=new JavaScriptSerializer();serializer.MaxJsonLength=16*1024*1024;
  object[] operations=serializer.DeserializeObject(patchJson) as object[];if(operations==null)throw new ArgumentException("Patch must be an array");
  IPatchStorage root=null;
  try{
   StgOpenStorage(path,null,0x12,IntPtr.Zero,0,out root);
   foreach(object raw in operations){
    var op=raw as System.Collections.Generic.Dictionary<string,object>;
    if(op==null||!op.ContainsKey("Op")||!op.ContainsKey("Path"))throw new ArgumentException("Invalid operation");
    string action=op["Op"] as string;var parts=op["Path"] as object[];
    if(parts==null||parts.Length==0)throw new ArgumentException("Nonempty segment array required");
    string[] names=new string[parts.Length];for(int i=0;i<parts.Length;i++)names[i]=Segment(parts[i]);
    var opened=new System.Collections.Generic.List<IPatchStorage>();IPatchStorage parent=root;
    try{
     for(int i=0;i<names.Length-1;i++){IPatchStorage child;parent.OpenStorage(names[i],null,0x12,IntPtr.Zero,0,out child);opened.Add(child);parent=child;}
     string leaf=names[names.Length-1];
     if(action=="CreateStorage"){
      IPatchStorage child=null;
      try{try{parent.OpenStorage(leaf,null,0x12,IntPtr.Zero,0,out child);}catch(COMException e){if(e.ErrorCode!=unchecked((int)0x80030002))throw;parent.CreateStorage(leaf,0x12,0,0,out child);}}finally{Release(child);}
     }else if(action=="WriteStream"){
      if(!op.ContainsKey("Data")||!(op["Data"] is string))throw new ArgumentException("Base64 data required");byte[] bytes=Convert.FromBase64String((string)op["Data"]);
      IStream stream=null;
      try{
       try{parent.OpenStream(leaf,IntPtr.Zero,0x12,0,out stream);}catch(COMException e){if(e.ErrorCode!=unchecked((int)0x80030002))throw;parent.CreateStream(leaf,0x12,0,0,out stream);}
       stream.Seek(0,0,IntPtr.Zero);
       if(bytes.Length>0){IntPtr count=Marshal.AllocHGlobal(4);try{stream.Write(bytes,bytes.Length,count);if(Marshal.ReadInt32(count)!=bytes.Length)throw new IOException("Short COM write");}finally{Marshal.FreeHGlobal(count);}}
      }finally{Release(stream);}
     }else if(action=="DeleteEntry"){parent.DestroyElement(leaf);}
     else throw new ArgumentException("Unknown patch operation");
    }finally{for(int i=opened.Count-1;i>=0;i--)Release(opened[i]);}
   }
   root.Commit(0);return operations.Length;
  }catch{if(root!=null){try{root.Revert();}catch{}}throw;}finally{Release(root);}
 }
}

# 安装包维修交接：先把表里的真实数据读出来

客户发来的 MSI 不能直接安装到排查机器上。我们想把其中一张表导出成 JSON，拿它跟上一版对照。现有 `src/MsiTableSnapshot.cs` 对短字符串看起来正常，一碰到空值、中文备注或嵌入的二进制数据，导出的内容就不可信了。

请交付可直接编译的这个生产文件，保留入口：

```csharp
public static string MsiTableSnapshot.Read(string path, string table)
```

返回值是 JSON，结构如下。`columns` 按 MSI 表的列序排列，`type` 是 Windows Installer 返回的原始列类型字符串，不要自己改大小写。每个 `rows` 元素都按同样列序放值，行顺序不限。

```json
{"columns":[{"name":"Key","type":"s72"},{"name":"Count","type":"I4"}],"rows":[["one",0],["two",null]]}
```

这份导出会用来判断“数据有没有丢”，所以要区分这些情况：

| MSI 单元格 | JSON 中应该保留什么 |
|---|---|
| 原生 NULL | `null`，不要变成0、空字符串或MSI的空整数哨兵 |
| 2字节/4字节整数 | JSON数字，正数、负数、0都要原样 |
| 普通/可本地化字符串 | 原字符串，包含中文、代理对、换行和引号，不能按固定缓冲区截断 |
| 非空 binary/object流 | 整个流的base64字符串，不能只读第一块，也不能按文本解码 |

原生 Windows Installer 将空字符串规范为空值时，按它读到的 NULL 输出即可。不能凭自己的猜测把所有字符串或整数统一格式化。表可能没有行，也可能有几十列和多条记录；两种情况下 `columns`、`rows` 仍是数组。

现场只能提供完整 Windows Server2022、.NET Framework 和系统 msi.dll；编译会引用 System.Web.Extensions。用真实 Windows Installer 数据库读取这些语义，不启动安装、不调用安装包内动作、不联网或加依赖。允许自行组织互操作类型和缓冲区，不绑定某个私有类名。

还有几个交接边界：path 必须指向已存在的普通 MSI 数据库，使用盘符绝对本地路径，中文/空格/方括号按字面处理；拒绝相对路径、UNC、目录、重解析点、ADS和不存在的路径。table 只接受1..31字符的 ASCII 标识符 `[A-Za-z_][A-Za-z0-9_]*`，不要把它当任意SQL。坏文件、缺表、非法输入和原生读取失败都抛异常，不能回一个成功空表。读取过程不得创建/写入/替换数据库，返回或失败后都关闭自己打开的MSI句柄；后续应能独占打开、重命名和删除文件。

只交付这个生产源码文件；测试、镜像和题面保持原样。验收会独立创建真实 MSI 表，比较类型、原始记录和流字节，并核对文件未改动；正确的等价实现同样接受。

