using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
public static class MsiTableSnapshot {
 [DllImport("msi.dll",CharSet=CharSet.Unicode)]static extern uint MsiOpenDatabase(string path,IntPtr persist,out uint db);
 [DllImport("msi.dll",CharSet=CharSet.Unicode)]static extern uint MsiDatabaseOpenView(uint db,string sql,out uint view);
 [DllImport("msi.dll")]static extern uint MsiViewExecute(uint view,uint record);
 [DllImport("msi.dll")]static extern uint MsiViewFetch(uint view,out uint record);
 [DllImport("msi.dll")]static extern uint MsiViewGetColumnInfo(uint view,int what,out uint record);
 [DllImport("msi.dll")]static extern uint MsiRecordGetFieldCount(uint record);
 [DllImport("msi.dll")]static extern int MsiRecordGetInteger(uint record,uint field);
 [DllImport("msi.dll")]static extern bool MsiRecordIsNull(uint record,uint field);
 [DllImport("msi.dll",CharSet=CharSet.Unicode)]static extern uint MsiRecordGetString(uint record,uint field,StringBuilder value,ref uint length);
 [DllImport("msi.dll")]static extern uint MsiRecordReadStream(uint record,uint field,byte[] buffer,ref uint length);
 [DllImport("msi.dll")]static extern uint MsiCloseHandle(uint handle);
 static void Check(uint code){if(code!=0)throw new Win32Exception((int)code,"Windows Installer database read failed");}
 static string Text(uint record,uint field){var b=new StringBuilder(1024);uint length=1024;MsiRecordGetString(record,field,b,ref length);return b.ToString();}
 static string Blob(uint record,uint field){using(var output=new MemoryStream()){var block=new byte[4096];uint count=(uint)block.Length;Check(MsiRecordReadStream(record,field,block,ref count));output.Write(block,0,(int)count);return Convert.ToBase64String(output.ToArray());}}
 public static string Read(string path,string table){
  if(String.IsNullOrWhiteSpace(path)||path.Length<3||!Regex.IsMatch(path,@"^[A-Za-z]:\\")||path.IndexOf(':',2)>=0||!File.Exists(path))throw new ArgumentException("existing absolute local MSI required");
  var attr=File.GetAttributes(path);if((attr&(FileAttributes.Directory|FileAttributes.ReparsePoint))!=0)throw new ArgumentException("ordinary MSI required");
  if(table==null||!Regex.IsMatch(table,@"\A[A-Za-z_][A-Za-z0-9_]{0,30}\z"))throw new ArgumentException("table identifier");
  uint db=0,view=0,names=0,types=0;
  try{
   Check(MsiOpenDatabase(path,IntPtr.Zero,out db));Check(MsiDatabaseOpenView(db,"SELECT * FROM `"+table+"`",out view));Check(MsiViewExecute(view,0));
   Check(MsiViewGetColumnInfo(view,0,out names));Check(MsiViewGetColumnInfo(view,1,out types));
   uint count=MsiRecordGetFieldCount(names);var columns=new List<object>();var ts=new List<string>();
   for(uint i=1;i<=count;i++){string type=Text(types,i);ts.Add(type);columns.Add(new {name=Text(names,i),type=type});}
   var rows=new List<object>();
   for(;;){uint record=0;uint code=MsiViewFetch(view,out record);if(code==259)break;Check(code);
    try{var cells=new object[count];for(uint i=1;i<=count;i++){if(MsiRecordIsNull(record,i)){cells[i-1]="";continue;}char type=Char.ToLowerInvariant(ts[(int)i-1][0]);if(type=='i')cells[i-1]=Math.Max(1,MsiRecordGetInteger(record,i));else if(type=='v')cells[i-1]=Blob(record,i);else cells[i-1]=Text(record,i);}rows.Add(cells);}finally{if(record!=0)MsiCloseHandle(record);}
   }
   var json=new JavaScriptSerializer();json.MaxJsonLength=64*1024*1024;return json.Serialize(new {columns=columns,rows=rows});
  }finally{if(types!=0)MsiCloseHandle(types);if(names!=0)MsiCloseHandle(names);if(view!=0)MsiCloseHandle(view);if(db!=0)MsiCloseHandle(db);}
 }
}

