using System;
using System.Collections.Generic;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Web.Script.Serialization;
public static class WindowsAccessProbe {
 static uint Map(uint mask,uint r,uint w,uint x,uint all){
  uint value=mask&0x0fffffffu;if((mask&0x80000000u)!=0)value|=r;if((mask&0x40000000u)!=0)value|=w;if((mask&0x20000000u)!=0)value|=x;if((mask&0x10000000u)!=0)value|=all;return value;
 }
 public static string Evaluate(string sddl,uint desired,uint genericRead,uint genericWrite,uint genericExecute,uint genericAll){
  if(String.IsNullOrWhiteSpace(sddl))throw new ArgumentException("sddl");
  var sd=new RawSecurityDescriptor(sddl);if(sd.Owner==null||sd.Group==null)throw new ArgumentException("owner and group required");
  uint request=Map(desired,genericRead,genericWrite,genericExecute,genericAll),allow=0,deny=0;
  using(var identity=WindowsIdentity.GetCurrent(TokenAccessLevels.Query)){
   var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);ids.Add(identity.User.Value);ids.Add("S-1-1-0");foreach(var g in identity.Groups)ids.Add(g.Value);
   if(sd.DiscretionaryAcl==null)allow=genericAll;
   else foreach(GenericAce ace in sd.DiscretionaryAcl){var a=ace as CommonAce;if(a==null||(a.AceFlags&AceFlags.InheritOnly)!=0||!ids.Contains(a.SecurityIdentifier.Value))continue;uint mask=Map(unchecked((uint)a.AccessMask),genericRead,genericWrite,genericExecute,genericAll);if(a.AceQualifier==AceQualifier.AccessDenied)deny|=mask;else if(a.AceQualifier==AceQualifier.AccessAllowed)allow|=mask;}
  }
  uint usable=allow&~deny;bool maximum=(request&0x02000000u)!=0;uint explicitMask=request&~0x02000000u;
  bool allowed=(explicitMask&usable)==explicitMask&&(!maximum||usable!=0);uint granted=allowed?(maximum?usable:request):0u;
  return new JavaScriptSerializer().Serialize(new {allowed=allowed,granted=granted});
 }
}

